'use strict';
const appliesToBranch=(card,id)=>!(card.branchRestricted||card.branchIds?.length)||card.branchIds?.includes(id);
const registrationURL=(card,branch='')=>location.origin+'/?join='+encodeURIComponent(card)+(branch?'&branch='+encodeURIComponent(branch):'');
branchForm=function(b={}){modal(b.id?'تعديل الفرع':'إضافة فرع',`<form id="branch-form"><input type="hidden" name="id" value="${esc(b.id||'')}"><label class="field"><span>اسم الفرع</span><input class="input" name="name" required maxlength="60" value="${esc(b.name||'')}"></label><label class="field"><span>العنوان · اختياري</span><input class="input" name="address" maxlength="160" value="${esc(b.address||'')}"></label><fieldset class="branch-card-options"><legend>البطاقات المتاحة في الفرع</legend>${db.shops.filter(s=>!s.archivedAt).map(s=>`<label class="terms"><input type="checkbox" name="cards" value="${esc(s.id)}" ${!b.id||appliesToBranch(s.card,b.id)?'checked':''}>${esc(s.card.title||s.name)}</label>`).join('')}<small>اختر بطاقة أو أكثر؛ يُحدّث الربط تلقائيًا.</small></fieldset><label class="terms"><input name="mapEnabled" type="checkbox" ${b.location?'checked':''}>تحديد موقع الفرع على الخريطة · اختياري</label><section id="branch-map-section" ${b.location?'':'hidden'}><p class="sub">افتح Google Maps وحدد موقع الفرع، ثم الصق رابط الموقع الكامل أو إحداثياته هنا.</p><a class="btn secondary small" id="open-google-map" target="_blank" rel="noopener">اختيار الموقع في Google Maps ↗</a><label class="field"><span>رابط Google Maps أو الإحداثيات</span><input class="input" id="branch-google-location" dir="ltr" placeholder="24.7136, 46.6753"><small id="map-input-help">استخدم رابط الموقع الكامل أو خط العرض وخط الطول.</small></label><div id="branch-map" aria-label="خريطة Google Maps"></div><div class="grid2"><label class="field">خط العرض<input class="input" name="lat" type="number" step="any" min="-85" max="85" value="${b.location?.lat??24.7136}"></label><label class="field">خط الطول<input class="input" name="lng" type="number" step="any" min="-180" max="180" value="${b.location?.lng??46.6753}"></label></div><small>الخريطة اختيارية؛ موقع الفرع لا يُستخدم لحساب المبيعات.</small></section><p class="error" id="branch-error"></p><button type="submit" class="btn primary full">حفظ الفرع</button></form>`);bindBranchMap(b.location);};
function bindBranchMap(){const el=document.getElementById('branch-map'),f=document.getElementById('branch-form');function draw(){const lat=Number(f.elements.namedItem('lat').value),lng=Number(f.elements.namedItem('lng').value);if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>85||Math.abs(lng)>180)return;const point=lat+','+lng;document.getElementById('open-google-map').href='https://www.google.com/maps?q='+encodeURIComponent(point);if(el.closest('[hidden]'))return;el.innerHTML=`<iframe title="موقع الفرع على Google Maps" src="https://maps.google.com/maps?q=${encodeURIComponent(point)}&z=16&output=embed&hl=ar" loading="eager" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;}f.elements.namedItem('mapEnabled').addEventListener('change',e=>{document.getElementById('branch-map-section').hidden=!e.target.checked;draw();});document.getElementById('branch-google-location').addEventListener('change',e=>{const value=e.target.value.trim(),match=value.match(/!3d(-?\d+(?:\.\d+)?)!4d(-?\d+(?:\.\d+)?)/)||value.match(/(?:@|[?&](?:q|query|ll)=)?(-?\d{1,2}(?:\.\d+)?),\s*(-?\d{1,3}(?:\.\d+)?)/);const help=document.getElementById('map-input-help');if(!match||Math.abs(Number(match[1]))>85||Math.abs(Number(match[2]))>180){help.textContent='لم نجد إحداثيات. افتح الرابط المختصر في Google Maps ثم انسخ الرابط الكامل، أو أدخل الإحداثيات.';return;}f.elements.namedItem('lat').value=match[1];f.elements.namedItem('lng').value=match[2];help.textContent='تم تحديث موقع الفرع على الخريطة.';draw();});['lat','lng'].forEach(k=>f.elements.namedItem(k).addEventListener('change',draw));draw();}

const advancedOwner=ownerHTML;
ownerHTML=function(){let html=advancedOwner();if(!['branches','join','overview'].includes(view))return html;const box=document.createElement('div');box.innerHTML=html;if(view==='branches'){const cards=db.shops.filter(s=>!s.archivedAt);box.querySelectorAll('.branch-grid article').forEach((el,i)=>{const b=businessBranches()[i];if(!b)return;el.querySelector('.branch-counts').innerHTML=`<span>${fmt(cards.filter(s=>appliesToBranch(s.card,b.id)).length)} بطاقة</span><span>${fmt(shop().employees.filter(e=>e.branchId===b.id).length)} موظف</span>`;el.querySelector('.actions').insertAdjacentHTML('beforebegin',`<div class="branch-tags">${cards.filter(s=>appliesToBranch(s.card,b.id)).map(s=>`<span class="pill">${esc(s.card.title||s.name)}</span>`).join('')}</div>${b.location?`<a class="branch-location" href="https://www.google.com/maps?q=${b.location.lat},${b.location.lng}" target="_blank" rel="noopener">عرض الموقع على الخريطة ↗</a>`:''}`);});box.querySelector('.branch-grid')?.insertAdjacentHTML('beforebegin','<p class="notice">الزيارات والمبيعات تُنسب لفرع الموظف وقت المسح. لحساب المبيعات، اطلب من الفريق إدخال مبلغ الشراء الاختياري؛ موقع العميل لا يحدد فرع البيع.</p>');}if(view==='join'){const cards=db.shops.filter(s=>!s.archivedAt);box.querySelectorAll('.registration-grid article').forEach((el,i)=>{const s=cards[i],branches=businessBranches().filter(b=>b.status==='active'&&appliesToBranch(s.card,b.id));el.insertAdjacentHTML('beforeend',`<details class="branch-links"><summary>روابط الفروع (${fmt(branches.length)})</summary><p class="sub">يحفظ رابط الفرع مصدر التسجيل. عمليات الشراء تُنسب لفرع الموظف، والرصيد مشترك بين فروع البطاقة.</p>${branches.map(b=>`<div class="branch-link-row"><strong>${esc(b.name)}</strong><input class="input" readonly dir="ltr" value="${esc(registrationURL(s.id,b.id))}" aria-label="رابط ${esc(s.card.title||s.name)} · ${esc(b.name)}"><div class="actions"><button class="btn secondary small" data-action="branch-link-copy" data-card="${s.id}" data-branch="${b.id}">نسخ الرابط</button><button class="btn secondary small" data-action="branch-link-qr" data-card="${s.id}" data-branch="${b.id}">تنزيل QR</button></div></div>`).join('')||'<p>لا توجد فروع نشطة لهذه البطاقة.</p>'}</details>`);});}if(view==='overview'){box.insertAdjacentHTML('beforeend',salesMatrix());}return box.innerHTML;};
function salesMatrix(){const range=analyticsRange(),cards=db.shops.filter(s=>!s.archivedAt&&(analyticsScope==='all'||s.id===(analyticsScope==='current'?shop().id:analyticsScope))),rows=[];for(const s of cards)for(const b of [...businessBranches(),{id:'',name:'بدون فرع'}]){if(branchFilter!=='all'&&b.id!==branchFilter)continue;const logs=s.logs.filter(l=>!l.undone&&l.type==='stamp'&&(l.branchId||'')===b.id&&l.time>=range.start&&l.time<=range.end),priced=logs.filter(l=>Number.isFinite(l.saleAmount));if(logs.length||appliesToBranch(s.card,b.id))rows.push({s,b,registrations:s.members.filter(m=>(m.registrationBranchId||'')===b.id&&m.joined>=range.start&&m.joined<=range.end).length,visits:logs.length,priced:priced.length,total:priced.reduce((n,l)=>n+l.saleAmount,0)});}rows.sort((a,b)=>b.total-a.total||b.visits-a.visits);return `<section class="panel mt"><h2>مقارنة البطاقات والفروع</h2><p class="sub">${esc(range.label)} · مرتبة حسب المبيعات المسجلة. إدخال المبلغ اختياري؛ هذه الأرقام لا تمثل فواتير لم تُدخل.</p><div class="table-scroll"><table><thead><tr><th>البطاقة</th><th>الفرع</th><th>الزيارات</th><th>تسجيلات جديدة</th><th>عمليات بمبلغ</th><th>مبيعات مسجلة · ريال</th><th>متوسط العملية المسجلة</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.s.card.title||r.s.name)}</td><td>${esc(r.b.name)}</td><td>${fmt(r.visits)}</td><td>${fmt(r.registrations)}</td><td>${fmt(r.priced)}</td><td>${r.priced?r.total.toLocaleString('ar-SA',{maximumFractionDigits:2}):'—'}</td><td>${r.priced?(r.total/r.priced).toLocaleString('ar-SA',{maximumFractionDigits:2}):'—'}</td></tr>`).join('')}</tbody></table></div></section>`;}
window.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||!['branch-link-copy','branch-link-qr'].includes(b.dataset.action))return;e.preventDefault();e.stopImmediatePropagation();if(window.RIJAA_DEMO)return;const url=registrationURL(b.dataset.card,b.dataset.branch);try{if(b.dataset.action==='branch-link-copy'){await navigator.clipboard.writeText(url);toast('تم نسخ رابط الفرع.');}else downloadBranchFile(qr(url),'image/svg+xml','branch-registration.svg');}catch{toast('تعذر نسخ الرابط. يمكنك تحديده ونسخه يدويًا.');}},true);
